import {test} from 'node:test';import assert from 'node:assert/strict';import {createCipheriv,randomBytes,createHash} from 'node:crypto';import {gzipSync} from 'node:zlib';import {unseal} from './decode.mjs';
const key=randomBytes(32);function seal(payload){const iv=randomBytes(12),c=createCipheriv('aes-256-gcm',key,iv);c.setAAD(Buffer.from('prokatmaxim'));const data=Buffer.concat([c.update(gzipSync(JSON.stringify(payload))),c.final()]);return{version:1,client:'prokatmaxim',iv:iv.toString('base64'),tag:c.getAuthTag().toString('base64'),data:data.toString('base64')};}
const file=name=>({name,data:Buffer.from('test').toString('base64'),sha256:createHash('sha256').update('test').digest('hex')});const payload=()=>({client:'prokatmaxim',password:'x'.repeat(32),files:['index.html','report.html','report.json'].map(file)});
test('valid payload verifies, wrong key and modified ciphertext fail',()=>{const e=seal(payload());assert.equal(unseal(e,key.toString('hex')).files.length,3);assert.throws(()=>unseal(e,randomBytes(32).toString('hex')));e.tag=Buffer.alloc(16).toString('base64');assert.throws(()=>unseal(e,key.toString('hex')));});
test('path traversal and duplicate paths fail',()=>{for(const name of ['../secret','index.html']){const p=payload();p.files.push(file(name));assert.throws(()=>unseal(seal(p),key.toString('hex')),/path/);}});
test('invalid file hash fails before extraction',()=>{const p=payload();p.files[0].sha256='bad';assert.throws(()=>unseal(seal(p),key.toString('hex')),/hash/);});
